#!/usr/bin/env bash
# The program output the tutorials, the first run and the home page show (docs/snippets/tutorials/, generated by
# src/tests/tutorials/capture.py) run again and compared: a failure when the output, or a number the prose quotes, no
# longer matches (numbers within 1e-6 relative, round-off below 1e-12 ignored). The FNL captures need a GPU and are
# refreshed by hand (capture.py --gpu).
source "$(dirname "$0")/common.sh"
set -e
for mode in flume-cpu-gnu prism-cpu-gnu ripple-cpu-gnu test-ripple-crest-criterion-cpu-gnu; do
   fobis build --mode "$mode" --varset ci_gnu
done
exe/.regression-venv/bin/python src/tests/tutorials/capture.py --check
